def shunting_yard(tokens):
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2
    }

    rpntokens = []
    opstack = []

    for token in tokens:
        if isinstance(token, int):
            rpntokens.append(token)
        else:
            while opstack and precedence.get(token, 0) <= precedence.get(opstack[-1], 0):
                rpntokens.append(opstack.pop())
            opstack.append(token)

    while opstack:
        rpntokens.append(opstack.pop())

    return rpntokens

print(shunting_yard([]))  # Should return []
print(shunting_yard([30]))  # Should return [30]
print(shunting_yard([10, '-', 5, '-', 2]))  # Should return [10, 5, 2, '-', '-']
